const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-87.160422, 56.271030);
  const aoi = point.buffer(50000); // 50km buffer around the point

  const date1 = '2020-07-13';
  const date2 = '2020-07-29';

  // 2. Data Acquisition
  const modisCollection = ee.ImageCollection('MODIS/061/MOD10A1')
    .select('NDSI_Snow_Cover');

  // Function to process an image for a given date
  const processDate = (date) => {
    const image = modisCollection
      .filterBounds(aoi)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .first();

    // The function returns an ee.Dictionary with counts or null if no image
    return ee.Algorithms.If(
      image,
      () => {
        const img = ee.Image(image);
        // Mask out clouds, water, night, etc. Values > 100 are non-ice/snow data.
        const qualityMask = img.lte(100);
        const maskedImg = img.updateMask(qualityMask);

        // Define ice as pixels with snow cover percentage > 15%
        const ice = maskedImg.gt(15);

        // Use ee.Image.pixelArea() to get area in sq. meters
        const iceAreaImage = ice.multiply(ee.Image.pixelArea());

        const stats = iceAreaImage.reduceRegion({
          reducer: ee.Reducer.sum(),
          geometry: aoi,
          scale: 500, // Native resolution of the dataset
          maxPixels: 1e9
        });

        // Get the area and convert from sq. meters to sq. kilometers
        const iceAreaSqKm = ee.Number(stats.get('NDSI_Snow_Cover')).divide(1e6);
        return ee.Dictionary({ 'area': iceAreaSqKm });
      },
      null // Return null if no image found
    );
  };

  // 3. Processing and Calculation
  const result1_dict = ee.Dictionary(processDate(date1));
  const result2_dict = ee.Dictionary(processDate(date2));

  // Fetch results asynchronously
  const result1_info = await ee.getInfo(result1_dict);
  const result2_info = await ee.getInfo(result2_dict);

  // 4. Validation & Final Answer
  if (!result1_info || !result2_info) {
    console.log(`Data status for ${date1}: ${result1_info ? 'Found' : 'Not Found'}`);
    console.log(`Data status for ${date2}: ${result2_info ? 'Found' : 'Not Found'}`);
    console.log('C1');
    return;
  }

  const area1 = result1_info.area;
  const area2 = result2_info.area;

  if (area1 === null || area2 === null) {
      console.log(`Calculation for ${date1} failed.`);
      console.log(`Calculation for ${date2} failed.`);
      console.log('C3');
      return;
  }

  console.log(`Sea ice area on ${date1}: ${area1.toFixed(2)} sq km`);
  console.log(`Sea ice area on ${date2}: ${area2.toFixed(2)} sq km`);

  if (area2 > area1) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
